import{_ as t,o,c as a,a3 as n}from"./chunks/framework.BTQ4eCVb.js";const g=JSON.parse('{"title":"AI Assistant — Deployment","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"AI Assistant — Deployment | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/ai"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"AI Assistant — Deployment | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/ai"}]]},"headers":[],"relativePath":"deployment/ai.md","filePath":"deployment/ai.md","lastUpdated":1787837771000}'),i={name:"deployment/ai.md"};function r(d,e,s,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-assistant-—-deployment" tabindex="-1">AI Assistant — Deployment <a class="header-anchor" href="#ai-assistant-—-deployment" aria-label="Permalink to &quot;AI Assistant — Deployment&quot;">​</a></h1><p>Operational notes for the billable <strong><code>ai</code></strong> Marketplace module and prepaid credit packs.</p><p>Companion readiness audit: <a href="./ai-production-readiness">AI production readiness</a>.</p><h2 id="what-ships" tabindex="-1">What ships <a class="header-anchor" href="#what-ships" aria-label="Permalink to &quot;What ships&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Notes</th></tr></thead><tbody><tr><td>Catalog</td><td><code>ai</code> ($29/$290) <strong>1.2.0</strong>, packs <code>ai-credits-1k</code> / <code>5k</code> / <code>20k</code> (require <code>ai</code>)</td></tr><tr><td>Migrations</td><td><code>2026_08_21_010000</code> register · <code>010100</code> permissions · <code>010200</code> tables · <code>010300</code> version bump <strong>1.0.1</strong> · <code>150423</code> version bump <strong>1.1.0</strong> · <code>2026_08_25_120000</code> version bump <strong>1.2.0</strong></td></tr><tr><td>Scheduler</td><td><code>ai:rollover-monthly-credits</code> (daily UTC period rollover)</td></tr><tr><td>Rate limits</td><td><code>throttle:ai</code> (30/min) on message send + Lead Copilot</td></tr><tr><td>Queues</td><td>None AI-specific — chat/copilot run <strong>synchronously</strong> on the web request</td></tr></tbody></table><h2 id="central-configuration" tabindex="-1">Central configuration <a class="header-anchor" href="#central-configuration" aria-label="Permalink to &quot;Central configuration&quot;">​</a></h2><p>Configure under <strong>Central → Settings → AI</strong> (encrypted settings store — not primarily <code>.env</code>):</p><ul><li><code>ai_enabled</code>, <code>ai_allow_platform</code>, <code>ai_allow_byok</code></li><li><code>ai_provider</code>, <code>ai_api_key</code>, <code>ai_api_base_url</code> (Ollama / OpenAI-compatible), default / fast / advanced models</li><li><code>ai_monthly_included_credits</code>, <code>ai_tokens_per_credit</code>, <code>ai_max_output_tokens</code></li><li><code>ai_tool_calling_enabled</code></li></ul><p>Keep <strong><code>APP_KEY</code></strong> stable so stored API keys remain decryptable after deploy.</p><h2 id="tenant-configuration" tabindex="-1">Tenant configuration <a class="header-anchor" href="#tenant-configuration" aria-label="Permalink to &quot;Tenant configuration&quot;">​</a></h2><p>After the workspace entitles <code>ai</code>:</p><ul><li>Settings → <strong>AI</strong> — requires <strong><code>ai.manage</code></strong> (+ <code>settings.update</code>); mode (<code>platform</code> | <code>byok</code>), provider catalog, optional tenant key and base URL, assistant toggles, instructions</li><li>Platform mode burns EloSync wallet credits (pre-provider ceiling + post-turn burn); BYOK does <strong>not</strong></li></ul><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><p>See <a href="./upgrade#ai-assistant-platform-100">Upgrade Guide — AI Assistant platform</a>. Migrate-only; do <strong>not</strong> <code>db:seed</code> in production.</p><h2 id="smoke" tabindex="-1">Smoke <a class="header-anchor" href="#smoke" aria-label="Permalink to &quot;Smoke&quot;">​</a></h2><ol><li>Central Test AI connection</li><li>Entitle <code>ai</code> → wallet grant</li><li>Ask EloSync + Lead Copilot</li><li>Zero credits → HTTP 402 on platform mode</li></ol><p>Full checklist: <a href="./ai-production-readiness">production readiness</a>.</p>',17)])])}const u=t(i,[["render",r]]);export{g as __pageData,u as default};
